"""
Implement GreedyMotifSearch.

Input: Integers k and t, followed by a space-separated collection of strings Dna.
Output: A collection of strings BestMotifs resulting from applying GreedyMotifSearch(Dna, k, t).
If at any step you find more than one Profile-most probable k-mer in a given string, use the one occurring first.

GreedyMotifSearch(Dna, k, t)
    BestMotifs ← motif matrix formed by first k-mers in each string from Dna
    for each k-mer Motif in the first string from Dna
        Motif1 ← Motif
        for i = 2 to t
            form Profile from motifs Motif1, …, Motifi - 1
            Motifi ← Profile-most probable k-mer in the i-th string in Dna
        Motifs ← (Motif1, …, Motift)
        if Score(Motifs) < Score(BestMotifs)
            BestMotifs ← Motifs
    return BestMotifs
"""

def parsing(text):
    text = text.split("\n")
    k, t = map(int, text[0].split())
    Dna = text[1:][0].split()
    return k, t, Dna

def ProfileMatrix(Motifs):
    k = len(Motifs[0])
    n = len(Motifs)
    seq_dict = {'A': 0, 'C': 1, 'G': 2, 'T': 3}
    P = [[0.0] * k for _ in range(4)]  # Fix matrix size

    for motif in Motifs:
        for i in range(k):
            P[seq_dict[motif[i]]][i] += 1

    for i in range(4):
        for j in range(k):
            P[i][j] /= n  # Normalize probabilities correctly

    return P

def Pr(Dna, Profile):
    seq_dict = {'A': 0, 'C': 1, 'G': 2, 'T': 3}
    prob = 1
    for i in range(len(Dna)):
        prob *= Profile[seq_dict[Dna[i]]][i]  # Fix indexing order
    return prob

def ProfileMostProbableKmer(Text, k, Profile):
    max_prob = -1
    most_probable_kmer = Text[:k]
    for i in range(len(Text) - k + 1):
        kmer = Text[i:i+k]
        prob = Pr(kmer, Profile)
        if prob > max_prob:
            max_prob = prob
            most_probable_kmer = kmer
    return most_probable_kmer

def Score(Motifs):
    k = len(Motifs[0])
    n = len(Motifs)
    seq_dict = {'A': 0, 'C': 1, 'G': 2, 'T': 3}
    P = [[0] * 4 for _ in range(k)]

    for motif in Motifs:
        for i in range(k):
            P[i][seq_dict[motif[i]]] += 1

    max_count = 0
    for i in range(k):
        max_count += max(P[i])
    return n * k - max_count

def GreedyMotifSearch(Dna, k, t):
    BestMotifs = [dna[:k] for dna in Dna]
    BestScore = Score(BestMotifs)

    for i in range(len(Dna[0]) - k + 1):
        Motifs = [Dna[0][i:i+k]]
        for j in range(1, t):
            P = ProfileMatrix(Motifs)
            Motifs.append(ProfileMostProbableKmer(Dna[j], k, P))
        currentScore = Score(Motifs)

        if currentScore < BestScore:
            BestMotifs = Motifs
            BestScore = currentScore

    return BestMotifs

